import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getCarById, updateCar } from "../../services/ApiCar";

export default function UpdateVoiture() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [car, setCar] = useState({
    model: "",
    matricule: "",
    prix: ""
  });
  const [file, setFile] = useState(null);

  useEffect(() => {
    const fetchCar = async () => {
      try {
        const res = await getCarById(id);
        setCar({
          model: res.data.model,
          matricule: res.data.matricule,
          prix: res.data.prix
        });
      } catch (err) {
        console.error("Erreur lors de la récupération de la voiture :", err);
      }
    };
    fetchCar();
  }, [id]);

  const handleChange = (e) => {
    setCar({ ...car, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const formData = new FormData();
      formData.append("model", car.model);
      formData.append("matricule", car.matricule);
      formData.append("prix", car.prix);
      if (file) {
        formData.append("image", file); // adapter le nom selon ce que ton backend attend
      }

      await updateCar(formData, id);
      alert("Voiture mise à jour avec succès !");
      navigate("/admin/voitures");
    } catch (err) {
      console.error("Erreur lors de la mise à jour :", err);
    }
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100">
      <form onSubmit={handleSubmit} className="bg-white p-8 rounded shadow-md w-full max-w-md">
        <h2 className="text-2xl font-bold mb-6 text-center text-gray-700">Modifier Voiture</h2>

        <div className="mb-4">
          <label className="block text-gray-600 text-sm mb-2">Modèle</label>
          <input
            type="text"
            name="model"
            value={car.model}
            onChange={handleChange}
            required
            className="w-full px-3 py-2 border rounded"
          />
        </div>

        <div className="mb-4">
          <label className="block text-gray-600 text-sm mb-2">Matricule</label>
          <input
            type="text"
            name="matricule"
            value={car.matricule}
            onChange={handleChange}
            required
            className="w-full px-3 py-2 border rounded"
          />
        </div>

        <div className="mb-4">
          <label className="block text-gray-600 text-sm mb-2">Prix</label>
          <input
            type="number"
            name="prix"
            value={car.prix}
            onChange={handleChange}
            required
            className="w-full px-3 py-2 border rounded"
          />
        </div>

        <div className="mb-6">
          <label className="block text-gray-600 text-sm mb-2">Image (facultatif)</label>
          <input
            type="file"
            accept="image/*"
            onChange={handleFileChange}
            className="w-full"
          />
        </div>

        <div className="flex justify-between">
          <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">
            ✅ Enregistrer
          </button>
          <button type="button" onClick={() => navigate("/admin/voitures")} className="bg-gray-400 text-white px-4 py-2 rounded hover:bg-gray-500">
            🔙 Annuler
          </button>
        </div>
      </form>
    </div>
  );
}
